        <button id="close-menu-btn" class="absolute top-4 right-4">
            <svg class="h-6 w-6" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <line x1="18" y1="6" x2="6" y2="18" />
